insert into public.tracks (chapter_id, title, embed_url, position)
select chapters.id, seed.title, seed.embed_url, 0
from (values
('portoes', 'Areia e portões', 'https://open.spotify.com/embed/playlist/37i9dQZF1DX4sWSpwq3LiO?utm_source=generator'),
('vagalumes', 'Noite na mata', 'https://open.spotify.com/embed/playlist/37i9dQZF1DWZd79rJ6a7lp?utm_source=generator')
) as seed(slug, title, embed_url)
join public.chapters on chapters.work_id = 'terras' and chapters.slug = seed.slug
where not exists (
  select 1 from public.tracks
  where tracks.chapter_id = chapters.id and tracks.embed_url = seed.embed_url
);

